import {t, ui, locale, onLanguageChange} from './i18n.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const labels={running:'In corso',review:'Da decidere',interrupted:'Da riprendere',ready:'Prossimi avvii',waiting:'In attesa di altre consegne'};
const date=value=>new Intl.DateTimeFormat(locale(),{dateStyle:'short',timeStyle:'short'}).format(new Date(value));

export function createTodayPanel({host,onAction=()=>{}}){
  let context={scopeId:'business',filter:'current',revision:''},projectId='',value=null,visible=false,loading=false,error='',controller=null,generation=0,refreshTimer=null,disposed=false;
  function itemHTML(item){
    return ui`<article class="today-item"><div class="today-item-heading"><span>${item.kind==='repository'?t('Repository'):t('Incarico')}</span><span>${escape(item.projectTitle)}</span></div><h4>${escape(item.title)}</h4>${item.progress?ui`<p>${t('{completed} di {total} passaggi salvati',{completed:item.progress.completed,total:item.progress.total})}</p>${item.progress.next?ui`<p class="today-next">Prossimo passaggio: <strong>${escape(item.progress.next)}</strong></p>`:ui`<p>Tutti i passaggi sono salvati: resta da preparare la consegna.</p>`}`:''}${item.kind==='repository'&&['paused','failed'].includes(item.status)?ui`<p>Apri il tentativo salvato e prepara una nuova revisione con una copia pulita.</p>`:''}${item.dependencies.length?ui`<div class="today-dependencies"><span>Attende l’approvazione di:</span>${item.dependencies.map(dependency=>dependency.available?`<button type="button" data-today-kind="task" data-today-id="${escape(dependency.id)}">${escape(dependency.title)} ↗</button>`:ui`<span>Una consegna non disponibile in questo progetto.</span>`).join('')}</div>`:''}${item.unblocks?ui`<p class="today-unlocks">${t('Approvando questa consegna sblocchi {count} incarichi.',{count:item.unblocks})}</p>`:''}<button type="button" class="ops-button" data-today-kind="${item.kind}" data-today-id="${escape(item.id)}">Apri il lavoro ↗</button></article>`;
  }
  function render(){
    if(!visible||disposed)return;
    host.setAttribute('aria-busy',String(loading));
    host.innerHTML=ui`<section class="today-panel"><header class="today-heading"><div><div class="eyebrow">IL PUNTO SUL TUO STUDIO</div><h3>Oggi, da dove ripartiamo?</h3><p>Decisioni, lavori da riprendere e prossimi passi dai dati salvati. Nessuna chiamata AI.</p></div><button type="button" class="ops-button" data-today-refresh${loading?' disabled':''}>Aggiorna</button></header>${error?ui`<p class="ops-error" role="alert">${escape(error)}</p>`:''}${!value?ui`<p role="status">${loading?t('Caricamento delle prossime azioni…'):t('Usa Aggiorna per riprovare.')}</p>`:ui`<label class="today-project-filter">Progetto<select id="today-project"><option value="">Tutti i progetti mostrati</option>${value.projects.map(project=>`<option value="${escape(project.id)}"${project.id===projectId?' selected':''}>${escape(project.title)}</option>`).join('')}</select></label><div class="today-totals">${['review','interrupted','running','ready'].map(key=>`<${value.counts[key]?'a':'div'}${value.counts[key]?` href="#today-${key}"`:''}><strong>${value.counts[key]}</strong><span>${escape(t(labels[key]))}</span></${value.counts[key]?'a':'div'}>`).join('')}</div><p class="today-caption">${t('Aggiornato: {time}',{time:date(value.generatedAt)})} · ${t('Gli avvii richiedono ancora la verifica di contesto, servizi e budget.')}</p>${Object.values(value.counts).some(count=>count>0)?'':ui`<p class="today-empty">Nessun lavoro da seguire negli ambiti mostrati. Puoi preparare un nuovo incarico dalle azioni rapide.</p>`}${['review','interrupted','running','ready','waiting'].filter(key=>value.groups[key].total>0).map(key=>{const group=value.groups[key];return ui`<section class="today-group" id="today-${key}"><div class="today-group-title"><h3>${escape(t(labels[key]))}</h3><span>${group.total}</span></div>${group.total?ui`<div class="today-grid">${group.items.map(itemHTML).join('')}</div>${group.total>group.items.length?ui`<button type="button" class="ops-button" data-today-kind="section" data-today-id="${key==='review'||key==='interrupted'?'review':'projects'}">${t('Apri l’elenco completo ({count})',{count:group.total})}</button>`:''}`:ui`<p class="today-empty">Nessun lavoro in questa sezione.</p>`}</section>`;}).join('')}<div class="today-support"><section><h3>Routine nelle prossime 24 ore</h3>${value.routines.total?value.routines.items.map(routine=>ui`<button type="button" data-today-kind="routine" data-today-id="${escape(routine.id)}"><strong>${escape(routine.title)}</strong><span>${escape(routine.projectTitle)} · ${escape(date(routine.nextRunAt))}</span>${routine.overdue?ui`<small>Orario raggiunto: controlla lo stato della routine.</small>`:''}</button>`).join(''):ui`<p>Nessuna routine prevista in questo intervallo.</p>`}<button type="button" class="ops-button" data-today-kind="section" data-today-id="routines">Apri le routine</button></section><section><h3>Prenditi cura del contesto</h3><p>${t('Fonti da aggiornare negli ambiti mostrati: {count}',{count:value.staleSources})}</p><div class="today-support-actions"><button type="button" class="ops-button" data-today-kind="section" data-today-id="sources">Controlla le fonti</button><button type="button" class="ops-button" data-today-kind="memory">Rivedi memoria dell’ambito attivo</button><button type="button" class="ops-button" data-today-kind="section" data-today-id="results">Guarda l’utilità dei risultati</button><button type="button" class="ops-button" data-today-kind="section" data-today-id="budgets">Controlla i budget</button></div></section></div>${!value.projects.length?ui`<button type="button" class="ops-button is-primary" data-today-kind="new-project">Crea il primo progetto</button>`:''}`}</section>`;
  }
  async function load(){
    if(!visible||disposed)return;
    controller?.abort();controller=new AbortController();const own=++generation;loading=true;error='';render();
    try{const query=new URLSearchParams({scopeId:context.filter==='all'?'*':context.scopeId});if(projectId)query.set('projectId',projectId);const response=await fetch(`/api/today?${query}`,{signal:controller.signal,cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(result.error||t('Le prossime azioni non sono disponibili.'));if(own===generation)value=result;}
    catch(cause){if(own===generation&&cause.name!=='AbortError')error=cause.message;}
    finally{if(own===generation){loading=false;render();}}
  }
  host.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||button.disabled)return;if(button.hasAttribute('data-today-refresh'))void load();else if(button.dataset.todayKind)onAction({kind:button.dataset.todayKind,id:button.dataset.todayId});});
  host.addEventListener('change',event=>{if(event.target.id==='today-project'){projectId=event.target.value;value=null;void load();}});
  const stopLanguage=onLanguageChange(render);
  const expire=()=>{disposed=true;controller?.abort();clearTimeout(refreshTimer);value=null;host.replaceChildren();};window.addEventListener('studio-session-expired',expire);
  return {load,setContext(next){const scopeChanged=next.scopeId!==context.scopeId||next.filter!==context.filter,changed=scopeChanged||next.revision!==context.revision;context={...context,...next};if(scopeChanged){controller?.abort();generation++;loading=false;projectId='';value=null;}if(changed&&visible){clearTimeout(refreshTimer);refreshTimer=setTimeout(load,100);}},setVisible(next){const changed=next&&!visible;visible=Boolean(next);host.hidden=!visible;if(changed)void load();else render();},dispose(){expire();stopLanguage();window.removeEventListener('studio-session-expired',expire);}};
}
